1	locals {
2	  # Pipeline exporter lists swap based on mode
3	  traces_exporters  = var.downstream_endpoint == "" ? ["datadog/connector", "datadog/exporter"] : ["datadog/connector", "otlp"]
4	  logs_exporters    = var.downstream_endpoint == "" ? ["datadog/exporter"] : ["otlp"]
5	  metrics_exporters = var.downstream_endpoint == "" ? ["datadog/exporter"] : ["otlp"]
6	
7	  # Shared structural skeleton — receivers, processors, connectors, extensions, service
8	  # are identical in both modes; only exporters differs.
9	  _otel_base = {
10	    receivers = {
11	      otlp = {
12	        protocols = {
13	          grpc = {
14	            endpoint = "0.0.0.0:4317"
15	          }
16	          http = {
17	            endpoint = "0.0.0.0:4318"
18	          }
19	        }
20	      }
21	    }
22	
23	    processors = {
24	      batch = {
25	        timeout             = "10s"
26	        send_batch_size     = 10
27	        send_batch_max_size = 75
28	      }
29	    }
30	
31	    connectors = {
32	      "datadog/connector" = {}
33	    }
34	
35	    extensions = {
36	      health_check = {
37	        endpoint = "$${env:MY_POD_IP}:13133"
38	      }
39	      "file_storage/persistent_queue" = {
40	        directory = "/var/lib/storage/queue"
41	      }
42	    }
43	
44	    service = {
45	      extensions = ["health_check", "file_storage/persistent_queue"]
46	      pipelines = {
47	        traces = {
48	          receivers  = ["otlp"]
49	          processors = []
50	          exporters  = local.traces_exporters
51	        }
52	
53	        logs = {
54	          receivers  = ["otlp"]
55	          processors = []
56	          exporters  = local.logs_exporters
57	        }
58	
59	        metrics = {
60	          receivers  = ["otlp", "datadog/connector"]
61	          processors = []
62	          exporters  = local.metrics_exporters
63	        }
64	      }
65	      telemetry = {
66	        logs = {
67	          encoding = "json"
68	        }
69	      }
70	    }
71	  }
72	
73	  # Direct (Datadog) exporter — active when downstream_endpoint is empty
74	  _exporters_direct = {
75	    exporters = {
76	      "datadog/exporter" = {
77	        api = {
78	          site = "datadoghq.com"
79	          key  = "$${env:DD_API_KEY}"
80	        }
81	        sending_queue = {
82	          enabled = true
83	          storage = "file_storage/persistent_queue"
84	        }
85	      }
86	    }
87	  }
88	
89	  # Downstream (OTLP/Vector) exporter — active when downstream_endpoint is set
90	  _exporters_downstream = {
91	    exporters = {
92	      otlp = {
93	        endpoint = var.downstream_endpoint
94	        tls = {
95	          insecure = true
96	        }
97	        sending_queue = {
98	          enabled    = true
99	          queue_size = 5000
100	        }
101	        retry_on_failure = {
102	          enabled          = true
103	          initial_interval = "5s"
104	          max_interval     = "30s"
105	          max_elapsed_time = "300s"
106	        }
107	      }
108	    }
109	  }
110	
111	  # Encode each exporter block to JSON first so the ternary operates on
112	  # uniform string types, bypassing Terraform's structural type check on
113	  # objects with different attribute names.
114	  _exporters_direct_json     = jsonencode(local._exporters_direct)
115	  _exporters_downstream_json = jsonencode(local._exporters_downstream)
116	
117	  # merge() combines the shared base with the active exporter block.
118	  otel_config = merge(
119	    local._otel_base,
120	    jsondecode(
121	      var.downstream_endpoint == "" ? local._exporters_direct_json : local._exporters_downstream_json
122	    )
123	  )
124	}
