34	resource "kubernetes_manifest" "otel-collector" {
35	  count = var.downstream_endpoint == "" ? 1 : 0
36	
37	  manifest = {
38	    "apiVersion" = "external-secrets.io/v1"
39	    "kind"       = "ExternalSecret"
40	    "metadata" = {
41	      "name"      = "otel-collector"
42	      "namespace" = var.namespace
43	    }
44	    "spec" = {
45	      "refreshInterval" = "1h0m0s"
46	      "secretStoreRef" = {
47	        "name" = "vault"
48	        "kind" = "ClusterSecretStore"
49	      }
50	      "target" = {
51	        "name"           = "otel-collector"
52	        "creationPolicy" = "Owner"
53	      }
54	      "data" = [
55	        {
56	          "secretKey" = "DD_API_KEY"
57	          "remoteRef" = {
58	            "key"      = "secret/data/saas/infrastructure/datadog-api-key"
59	            "property" = "apiKey"
60	          }
61	        },
62	      ]
63	    }
64	  }
65	  depends_on = [kubernetes_namespace.this]
66	}
