170	      repository = var.otel_image
171	      tag        = var.image_tag_version
172	    }
173	    statefulset = {
174	      persistentVolumeClaimRetentionPolicy = {
175	        enabled     = true
176	        whenDeleted = "Delete"
177	        whenScaled  = "Delete"
178	      }
179	
180	      volumeClaimTemplates = [
181	        {
182	          metadata = {
183	            name = "otel-collector-data"
184	          }
185	          spec = {
186	            accessModes = ["ReadWriteOnce"]
187	            resources = {
188	              requests = {
189	                storage = var.otel_pv_size
190	              }
191	            }
192	            //storageClassName = var.otel_storage_class_name
193	          }
194	        }
195	      ]
196	    }
197	
198	    extraVolumeMounts = [{
199	      name      = "otel-collector-data"
200	      mountPath = "/var/lib/storage/queue"
201	    }]
202	
203	    initContainers = [{
