207	      volumeMounts = [{
208	        name      = "otel-collector-data"
209	        mountPath = "/var/lib/storage/queue"
210	      }]
211	    }]
212	
213	    nameOverride = "processor"
214	
215	    replicaCount = var.otel_collector_replicas
216	
217	    service = {
218	      type      = "ClusterIP"
219	      clusterIP = "None" # Headless service for statefulset
220	    }
221	
222	    annotations = var.annotations
223	    podLabels = {
224	      "ic-ops.net/otel"           = "processor"
225	      "app.kubernetes.io/part-of" = "opentelemetry-collector"
226	    }
227	
228	    serviceAccount = {
229	      create      = true,
230	      name        = var.otel_sa_name,
231	      annotations = var.sa_annotations
232	    }
233	
234	    command = {
235	      extraArgs = var.extra_args
236	    }
237	
238	    extraEnvsFrom = var.downstream_endpoint == "" ? [{
239	      secretRef = {
240	        name = "otel-collector"
241	      }
242	    }] : []
243	
244	    #presets = {
245	    # enables the k8sattributesprocessor and adds it to the traces, metrics, and logs pipelines
246	    #kubernetesAttributes = {
247	    #  enabled = true
248	    #  extractAllPodLabels = true
249	    #  extractAllPodAnnotations = true
250	    #}
251	    #}
252	
253	    ports = {
254	      otlp = {
255	        enabled       = true
256	        containerPort = 4317
257	        servicePort   = 4317
258	        protocol      = "TCP"
259	        appProtocol   = "grpc"
260	      }
261	      otlp-http = {
262	        enabled       = true
263	        containerPort = 4318
264	        servicePort   = 4318
265	        protocol      = "TCP"
266	      }
267	      jaegar-compact = {
268	        enabled = false
269	      }
270	      jaeger-grpc = {
271	        enabled = false
272	      }
273	      jaeger-thrift = {
274	        enabled = false
275	      }
276	      zipkin = {
277	        enabled = false
278	      }
279	    }
280	
281	    config = local.otel_config
282	  })]
283	
284	  depends_on = [
285	    kubernetes_namespace.this,
286	    kubernetes_manifest.otel-collector
287	  ]
288	
289	  lifecycle {
290	    create_before_destroy = false
291	  }
292	}
